AS $$
BEGIN
    INSERT INTO public."Seller" ("code", "name", "email")
    VALUES (p_code, p_name, p_email)
    RETURNING id INTO p_seller_id;

    p_mensaje_resultado := 'SUCCESS: Vendedor creado con ID ' || p_seller_id;
EXCEPTION
    WHEN OTHERS THEN
        p_mensaje_resultado := 'ERROR: ' || SQLERRM;
END;
$$;


