-- Archivo: spQuotationStateEliminar.sql

CREATE OR REPLACE PROCEDURE public."spQuotationStateEliminar"(
    p_id INT,
    p_acting_user_id INT,
    INOUT p_mensaje_resultado TEXT
)
LANGUAGE plpgsql AS $$
BEGIN
